import{_ as t,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const i="/assets/image%20(1).DRUlGwKh.png",p=JSON.parse('{"title":"Devtunnels","description":"","frontmatter":{},"headers":[],"relativePath":"installation-guidelines/getting-started/devtunnels.md","filePath":"installation-guidelines/getting-started/devtunnels.md"}'),n={name:"installation-guidelines/getting-started/devtunnels.md"};function s(l,e,d,u,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="devtunnels" tabindex="-1">Devtunnels <a class="header-anchor" href="#devtunnels" aria-label="Permalink to &quot;Devtunnels&quot;">​</a></h1><p><strong>What Are Dev Tunnels?</strong></p><p>Dev Tunnels is a feature built into <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code (VS Code)</a>. It enables developers to securely expose local web services to the public internet without wrestling with complex networking or cloud infrastructure. Although Dev Tunnels are perfect for ad-hoc testing and development, remember that they are not designed for production workloads.</p><h4 id="key-benefits-of-dev-tunnels" tabindex="-1">Key Benefits of Dev Tunnels <a class="header-anchor" href="#key-benefits-of-dev-tunnels" aria-label="Permalink to &quot;Key Benefits of Dev Tunnels&quot;">​</a></h4><p><strong>Flexibility:</strong> Ideal for testing webhooks, APIs, and various integrations, especially for services like TradingView.</p><p><strong>Security:</strong> Dev Tunnels establish encrypted, secure connections between your local environment and the public internet.</p><p><strong>Simplicity:</strong> Skip the hassle of configuring cloud servers or proxies. With just a few clicks, you have a publicly accessible URL.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><p>Before diving into the setup, ensure you have the following:</p><ul><li><strong>Visual Studio Code (VS Code):</strong> Installed on your machine.</li><li><strong>Tradeboard:</strong> Running locally with <code>uv run app.py</code> (port 5000 by default).</li><li><strong>TradingView Account:</strong> Set up for alert creation.</li><li><strong>GitHub or Microsoft Account:</strong> For authenticating with Dev Tunnels.</li></ul><h3 id="step-by-step-setup-guide" tabindex="-1">Step-by-Step Setup Guide <a class="header-anchor" href="#step-by-step-setup-guide" aria-label="Permalink to &quot;Step-by-Step Setup Guide&quot;">​</a></h3><h4 id="_1-start-and-verify-tradeboard" tabindex="-1">1. Start and Verify Tradeboard <a class="header-anchor" href="#_1-start-and-verify-tradeboard" aria-label="Permalink to &quot;1. Start and Verify Tradeboard&quot;">​</a></h4><p>Begin by launching your Tradeboard application locally from your VS Code. Open your browser and navigate to the Tradeboard dashboard (e.g., <a href="http://127.0.0.1:5000/dashboard" target="_blank" rel="noreferrer">http://127.0.0.1:5000/dashboard</a>) to verify that the service is up and running.</p><h4 id="_2-create-a-dev-tunnel-in-vs-code" tabindex="-1">2. Create a Dev Tunnel in VS Code <a class="header-anchor" href="#_2-create-a-dev-tunnel-in-vs-code" aria-label="Permalink to &quot;2. Create a Dev Tunnel in VS Code&quot;">​</a></h4><ul><li><strong>Open VS Code</strong> where your Tradeboard project is running.</li><li>Navigate to the <strong>Ports</strong> tab located at the bottom of the VS Code interface.</li><li>Click on <strong>“Forward a Port”</strong> to start the process.</li></ul><h4 id="_3-configure-the-forwarded-port" tabindex="-1">3. Configure the Forwarded Port <a class="header-anchor" href="#_3-configure-the-forwarded-port" aria-label="Permalink to &quot;3. Configure the Forwarded Port&quot;">​</a></h4><ul><li>Enter the port number on which Tradeboard is running (e.g., <strong>5000</strong>), then press <strong>Enter</strong>.</li><li>This action forwards the specified port to a public URL.</li></ul><h4 id="_4-set-port-visibility-to-public" tabindex="-1">4. Set Port Visibility to Public <a class="header-anchor" href="#_4-set-port-visibility-to-public" aria-label="Permalink to &quot;4. Set Port Visibility to Public&quot;">​</a></h4><ul><li>In the <strong>Ports</strong> tab, right-click on the forwarded address.</li><li>Select <strong>“Port Visibility”</strong> and then <strong>“Public.”</strong></li><li>VS Code will warn you that this action will expose your service to the internet, confirm to proceed.</li><li>If prompted, sign up or log in using your <strong>GitHub or Microsoft account</strong> to create an encrypted URL.</li><li>Once completed, verify your new public URL.</li></ul><h4 id="_5-obtain-your-custom-webhook-url" tabindex="-1">5. Obtain Your Custom Webhook URL <a class="header-anchor" href="#_5-obtain-your-custom-webhook-url" aria-label="Permalink to &quot;5. Obtain Your Custom Webhook URL&quot;">​</a></h4><ul><li>Refer to the <strong>Tradeboard documentation</strong> and navigate to <strong>“API Documentation” → “V1” → “Orders API” → “Placeorder”.</strong></li><li>Copy the custom domain information provided. For instance:<br><code>POST https://your-custom-domain/api/v1/placeorder</code></li><li>Append your unique Dev Tunnel URL to this endpoint.<br> &amp;#xNAN;<em>Example:</em><br><code>https://h03ml9j.5000.inc1.devtunnels.ms/api/v1/placeorder</code></li></ul><h4 id="_6-create-an-alert-in-tradingview" tabindex="-1">6. Create an Alert in TradingView <a class="header-anchor" href="#_6-create-an-alert-in-tradingview" aria-label="Permalink to &quot;6. Create an Alert in TradingView&quot;">​</a></h4><ul><li>Open your desired chart on <strong>TradingView</strong> and configure the conditions for your alert.</li><li>Click the <strong>“Alert”</strong> icon to create a new alert.</li><li>In the alert settings, navigate to the <strong>“Notifications”</strong> tab.</li><li>Enable the <strong>“Webhook URL”</strong> option and paste your custom Tradeboard webhook URL from the previous step.</li></ul><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><h4 id="_7-configure-the-tradingview-alert-message-json-payload" tabindex="-1">7. Configure the TradingView Alert Message (JSON Payload) <a class="header-anchor" href="#_7-configure-the-tradingview-alert-message-json-payload" aria-label="Permalink to &quot;7. Configure the TradingView Alert Message (JSON Payload)&quot;">​</a></h4><p>The JSON payload sent by TradingView is pivotal, it instructs Tradeboard on how to execute orders.</p><ul><li>Return to the <a href="https://docs.algo.wesoftcorp.com/api-documentation/v1/orders-api/placeorder" target="_blank" rel="noreferrer"><strong>Tradeboard documentation</strong></a> and copy the JSON payload structure.</li><li>Ensure your TradingView alert message matches the required format so that Tradeboard can correctly interpret and act on the alert.</li></ul><h4 id="_8-trigger-an-alert-and-verify" tabindex="-1">8. Trigger an Alert and Verify <a class="header-anchor" href="#_8-trigger-an-alert-and-verify" aria-label="Permalink to &quot;8. Trigger an Alert and Verify&quot;">​</a></h4><ul><li>Activate your TradingView alert settings and position the alert trigger line near the current trading range.</li><li>Once the alert is live, monitor Tradeboard’s <strong>Orderbook</strong> and <strong>live mode</strong> to confirm that orders are being executed as expected.</li><li>When the order is successfully placed and completed, the alert will cease, marking a successful integration.</li></ul><figure><img src="https://i0.wp.com/www.marketcalls.in/wp-content/uploads/2025/02/image-8.png?resize=854%2C637&amp;ssl=1" alt="" height="637" width="854"><figcaption></figcaption></figure><hr><h3 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h3><p>By leveraging Dev Tunnels, you can effortlessly and securely connect TradingView alerts to your local Tradeboard instance. This setup is ideal for testing new trading strategies, exploring API integrations, and streamlining your algorithmic trading workflow. Remember, while Dev Tunnels are fantastic for development and testing, a more robust solution (such as cloud servers) is recommended for production environments.</p><p>Embrace this streamlined approach and elevate your algo trading game today!</p>',34)])])}const b=t(n,[["render",s]]);export{p as __pageData,b as default};
